function displayScheduleTime(value: string): string {
  return value
    .replace(/^12(:\d{2})? AM$/, "凌晨 12$1")
    .replace(/^12(:\d{2})? PM$/, "中午 12$1")
    .replace(/^(.*) AM$/, "上午 $1")
    .replace(/^(.*) PM$/, "下午 $1");
}

